style.css:
@-moz-document domain("mail.google.com") {
/* --- COLOR CONTROL PANEL --- */
  :root {
    -main-bg: #2d1b1e;          /* Main background color */
    -sidebar-bg: #3b2529;       /* Sidebar background color */
    -header-bg: #241416;        /* Top search bar area */
    -text-color: #e0c9cc;       /* Primary text color */
    -accent-color: #8c5e63;     /* Compose button and accents */
    -highlight-bg: #4a2e32;     /* Selected email row color */
    -unread-text: #f2e1e3;      /* Unread email emphasis */
  }

  /* --- DO NOT CHANGE BELOW THIS LINE --- */
  body, .G-atb, .aeF, .nr, .nH, .nH.oy8Mbf {
      background-color: var(--main-bg) !important;
      color: var(--text-color) !important;
  }

  .ajl, .inbox-nav, .left-nav, .n3 {
      background-color: var(--sidebar-bg) !important;
  }

  .T-I-KE {
      background-color: var(--accent-color) !important;
      color: #ffffff !important;
      border: none !important;
  }

  header, .gb_re, .asV, .gb_Sd {
      background-color: var(--header-bg) !important;
      border-bottom: 1px solid var(--highlight-bg) !important;
  }

  .x7, .yO {
      background-color: var(--highlight-bg) !important;
  }

  .gb_He form {
      background-color: var(--sidebar-bg) !important;
      border-radius: 8px !important;
  }

  .zF, .bAW, .y6 {
      color: var(--unread-text) !important;
  }

  .aHs-bnx, .aHs-bnt, .gb_Tc {
      filter: sepia(0.3) hue-rotate(315deg) brightness(1.2) !important;
  }
}
